	class CFSLoadListMessageActionTest : ImportMessageActionTest
	{
		public void TestExecuteAction_ImportLoadList()
		{
			var factoryProvider = new BusinessObjectFactoryProvider(Factory);

			int noOfLoadLists = Factory.GetDatabaseCount(typeof(CFSLoadListConsol));

			var buffer = new NotificationBuffer();
			var message = CreateMessage(factoryProvider.Current);
			message.EM_MessageText = messageBody;
			message.Interchange.EI_HeaderText = messageHeader;
			message.Interchange.EI_FooterText = messageFooter;

			var action = new CFSLoadListMessageAction(factoryProvider);
			List<ITransactionParticipant> forSave;
			Assert(action.ExecuteAction(message, buffer, out forSave));
			Factory.Save();
			AssertEquals(noOfLoadLists + 1, Factory.GetDatabaseCount(typeof(CFSLoadListConsol)));
		}

